type Product = {
  id: number;
  name: string;
  store: string;
  category: string;
  price: number;
  oldPrice?: number;
  emoji: string;
  color: string;
  featured?: boolean;
};

type StoreInfo = {
  id: number;
  name: string;
  category: string;
  zone: string;
  emoji: string;
  color: string;
  rating: number;
  verified: boolean;
};

