const occasions = [
  { id: "desayuno", label: "Desayuno", icon: Coffee, category: "Gastronomía" },
  { id: "regalo", label: "Un regalo", icon: Gift, category: "Regalos" },
  { id: "look", label: "Nuevo look", icon: Shirt, category: "Moda" },
  { id: "tech", label: "Tecnología", icon: Laptop, category: "Tecnología" },
  { id: "noche", label: "Plan de noche", icon: Moon, category: "Gastronomía" },
  { id: "evento", label: "Un evento", icon: PartyPopper, category: "Servicios" },
];

function SectionHeader({
  eyebrow,
  title,
  description,
  href = "/explorar",
}: {
  eyebrow?: string;
  title: string;
  description?: string;
  href?: string;
}) {
  return (
    <div className="mb-6 flex items-end justify-between gap-4">
      <div>
        {eyebrow && (
          <p className="mb-2 text-[10px] font-bold uppercase tracking-[0.2em] text-violet-600">
            {eyebrow}
          </p>
        )}
        <h2 className="text-xl font-bold tracking-tight sm:text-2xl">{title}</h2>
        {description && (
          <p className="mt-1 text-sm text-zinc-500">{description}</p>
        )}
      </div>
      <Link
        href={href}
        className="flex shrink-0 items-center gap-1 text-xs font-semibold text-violet-600 transition hover:gap-2 sm:text-sm"
      >
        Ver todos <ArrowRight size={15} />
      </Link>
    </div>
  );
}

function ProductCard({ product }: { product: Product }) {
  return (
    <article className="group min-w-0">
      <Link href="/explorar" className="block">
        <div
          className={`relative flex aspect-[4/4.5] items-center justify-center overflow-hidden rounded-2xl bg-gradient-to-br ${product.color}`}
        >
          <span className="select-none text-6xl transition duration-300 group-hover:scale-110 sm:text-7xl">
            {product.emoji}
          </span>

          {product.oldPrice && (
            <span className="absolute left-3 top-3 rounded-full bg-white px-2.5 py-1 text-[10px] font-bold text-rose-600 shadow-sm">
              OFERTA
            </span>
          )}

          <button
            type="button"
            aria-label={`Guardar ${product.name}`}
            onClick={(event) => event.preventDefault()}
            className="absolute right-3 top-3 flex h-8 w-8 items-center justify-center rounded-full bg-white/90 text-zinc-700 shadow-sm transition hover:text-rose-500"
          >
            <Heart size={16} />
          </button>

          <span className="absolute bottom-3 right-3 rounded-lg bg-white/90 px-2 py-1 text-[10px] font-semibold text-zinc-600 backdrop-blur">
            {product.category}
          </span>
        </div>
      </Link>

      <div className="pt-3">
        <p className="truncate text-[11px] text-zinc-500">{product.store}</p>
        <Link href="/explorar">
          <h3 className="mt-1 truncate text-sm font-semibold transition group-hover:text-violet-600">
            {product.name}
          </h3>
        </Link>
        <div className="mt-2 flex flex-wrap items-center gap-2">
          <span className="text-sm font-bold">${product.price.toFixed(2)}</span>
          {product.oldPrice && (
            <span className="text-xs text-zinc-400 line-through">
              ${product.oldPrice.toFixed(2)}
            </span>
          )}
        </div>
      </div>
    </article>
  );
}

function StoreCard({ store }: { store: StoreInfo }) {
  return (
    <Link
      href="/tiendas"
      className="group block overflow-hidden rounded-2xl border border-zinc-200/80 bg-white transition duration-300 hover:-translate-y-1 hover:shadow-lg hover:shadow-zinc-200/50 dark:border-zinc-800 dark:bg-zinc-900"
    >
      <div
        className={`relative flex h-32 items-center justify-center bg-gradient-to-br ${store.color}`}
      >
        <span className="text-6xl transition duration-300 group-hover:scale-110">
          {store.emoji}
        </span>
        {store.verified && (
          <span className="absolute left-3 top-3 rounded-full bg-white/90 px-2.5 py-1 text-[10px] font-bold text-emerald-700">
            ✓ Verificada
          </span>
        )}
        <span className="absolute bottom-3 right-3 flex items-center gap-1 rounded-full bg-white/90 px-2 py-1 text-xs font-bold text-zinc-800">
          <Star size={12} className="fill-amber-400 text-amber-400" />
          {store.rating}
        </span>
      </div>

      <div className="p-4">
        <h3 className="font-bold">{store.name}</h3>
        <p className="mt-1 text-xs text-zinc-500">{store.category}</p>
        <p className="mt-3 flex items-center gap-1 text-xs text-zinc-400">
          <MapPin size={13} /> {store.zone}, Guayaquil
        </p>
      </div>
    </Link>
  );
}

export function MarketplaceHomePage() {
  const [activeCategory, setActiveCategory] = useState("Todas");
  const [activeOccasion, setActiveOccasion] = useState("");

  const visibleProducts =
    activeCategory === "Todas"
      ? products
      : activeCategory === "Ofertas"
        ? products.filter((product) => product.oldPrice)
        : products.filter((product) => product.category === activeCategory);

  const occasion = occasions.find((item) => item.id === activeOccasion);
  const occasionProducts = occasion
    ? products.filter((product) => product.category === occasion.category)
    : products.slice(0, 4);

  return (
    <div className="min-w-0">
      {/* Hero */}
      <section className="relative overflow-hidden border-b border-zinc-200/70 bg-[#faf9ff] px-5 py-14 dark:border-zinc-800 dark:bg-zinc-900 sm:py-20 md:px-10 md:py-24">
        <div className="pointer-events-none absolute -right-20 -top-32 h-96 w-96 rounded-full bg-violet-300/30 blur-[100px]" />
        <div className="pointer-events-none absolute -bottom-48 left-1/3 h-96 w-96 rounded-full bg-pink-200/30 blur-[100px]" />

        <div className="relative mx-auto max-w-5xl text-center">
          <span className="mb-6 inline-flex items-center gap-2 rounded-full border border-violet-200 bg-white/80 px-3 py-1.5 text-[11px] font-semibold text-violet-700 shadow-sm dark:border-violet-900 dark:bg-zinc-900 dark:text-violet-300">
            <Sparkles size={13} />
            TU CIUDAD, UNA NUEVA FORMA DE COMPRAR
          </span>

          <h1 className="mx-auto max-w-4xl text-4xl font-bold leading-[1.1] tracking-tight sm:text-6xl lg:text-7xl">
            La variedad de la ciudad,
            <span className="block font-serif italic text-violet-600">
              organizada para ti.
            </span>
          </h1>

          <p className="mx-auto mt-6 max-w-xl text-sm leading-7 text-zinc-500 sm:text-base">
            Descubre productos, negocios y lugares únicos de Guayaquil.
            Todo lo que buscas, más cerca de lo que imaginas.
          </p>

          <form
            onSubmit={(event) => {
              event.preventDefault();
              window.location.href = "/explorar";
            }}
            className="mx-auto mt-9 flex max-w-2xl items-center gap-3 rounded-2xl border border-zinc-200 bg-white p-2 shadow-xl shadow-violet-900/5 dark:border-zinc-700 dark:bg-zinc-950"
          >
            <Search className="ml-3 shrink-0 text-zinc-400" size={21} />
            <input
              aria-label="Buscar productos y tiendas"
              placeholder="¿Qué estás buscando hoy?"
              className="min-w-0 flex-1 bg-transparent py-3 text-sm outline-none placeholder:text-zinc-400"
            />
            <button
              type="submit"
              className="rounded-xl bg-violet-600 px-5 py-3 text-sm font-semibold text-white transition hover:bg-violet-700"
            >
              Buscar
            </button>
          </form>

          <div className="mt-5 flex flex-wrap items-center justify-center gap-x-5 gap-y-2 text-xs text-zinc-500">
            <span className="flex items-center gap-1.5">
              <span className="h-2 w-2 rounded-full bg-emerald-500" />
              Negocios locales
            </span>
            <span className="flex items-center gap-1.5">
              <span className="h-2 w-2 rounded-full bg-violet-500" />
              Descubrimientos únicos
            </span>
            <span className="flex items-center gap-1.5">
              <span className="h-2 w-2 rounded-full bg-amber-500" />
              Ofertas especiales
            </span>
          </div>
        </div>
      </section>

      {/* Categorías */}
      <section className="px-5 py-9 md:px-10">
        <div className="mx-auto max-w-6xl">
          <div className="mb-5 flex items-center justify-between">
            <h2 className="text-sm font-bold">Explora por categoría</h2>
            <Link href="/explorar" className="text-xs font-semibold text-violet-600">
              Explorar todo →
            </Link>
          </div>

          <div className="grid grid-cols-4 gap-3 sm:grid-cols-4 lg:grid-cols-8">
            {categories.map(({ name, icon: Icon, color }) => (
              <button
                key={name}
                type="button"
                onClick={() => {
                  setActiveCategory(name);
                  document.getElementById("productos")?.scrollIntoView({
                    behavior: "smooth",
                  });
                }}
                className="group flex flex-col items-center gap-2.5 rounded-2xl border border-transparent py-3 transition hover:border-zinc-200 hover:bg-zinc-50 dark:hover:border-zinc-800 dark:hover:bg-zinc-900"
              >
                <span className={`flex h-12 w-12 items-center justify-center rounded-2xl transition group-hover:scale-105 ${color}`}>
                  <Icon size={21} />
                </span>
                <span className="text-center text-[10px] font-semibold sm:text-xs">
                  {name}
                </span>
              </button>
            ))}
          </div>
        </div>
      </section>

      {/* Productos */}
      <section id="productos" className="scroll-mt-20 px-5 py-10 md:px-10">
        <div className="mx-auto max-w-6xl">
          <SectionHeader
            eyebrow="Hecho para descubrir"
            title="Vitrina de hoy"
            description="Productos que vale la pena conocer."
          />

          <div className="mb-6 flex gap-2 overflow-x-auto pb-2">
            {["Todas", ...categories.map((category) => category.name)].map(
              (category) => (
                <button
                  key={category}
                  type="button"
                  onClick={() => setActiveCategory(category)}
                  className={`shrink-0 rounded-full border px-4 py-2 text-xs font-semibold transition ${
                    activeCategory === category
                      ? "border-violet-600 bg-violet-600 text-white"
                      : "border-zinc-200 text-zinc-500 hover:border-violet-300 dark:border-zinc-800"
                  }`}
                >
                  {category}
                </button>
              ),
            )}
          </div>

          <div className="grid grid-cols-2 gap-x-4 gap-y-7 sm:grid-cols-3 lg:grid-cols-4 lg:gap-x-6">
            {visibleProducts.slice(0, 8).map((product) => (
              <ProductCard key={product.id} product={product} />
            ))}
          </div>

          {visibleProducts.length === 0 && (
            <p className="py-12 text-center text-sm text-zinc-500">
              No hay productos de esta categoría todavía.
            </p>
          )}
        </div>
      </section>

      {/* Banner */}
      <section className="px-5 py-8 md:px-10">
        <div className="relative mx-auto max-w-6xl overflow-hidden rounded-3xl bg-violet-600 px-6 py-10 text-white sm:px-10 sm:py-14">
          <div className="pointer-events-none absolute -right-10 -top-24 h-72 w-72 rounded-full border-[40px] border-white/10" />
          <div className="pointer-events-none absolute -bottom-32 right-1/3 h-64 w-64 rounded-full bg-fuchsia-400/30 blur-3xl" />

          <div className="relative max-w-xl">
            <span className="inline-flex items-center gap-2 rounded-full bg-white/15 px-3 py-1.5 text-[10px] font-bold uppercase tracking-widest">
              <Sparkles size={13} /> Hecho en tu ciudad
            </span>
            <h2 className="mt-5 text-3xl font-bold leading-tight sm:text-4xl">
              Detrás de cada compra, hay una historia local.
            </h2>
            <p className="mt-4 max-w-md text-sm leading-6 text-violet-100">
              Encuentra marcas independientes, propuestas creativas y negocios
              que hacen única a Guayaquil.
            </p>
            <Link
              href="/tiendas"
              className="mt-7 inline-flex items-center gap-2 rounded-xl bg-white px-5 py-3 text-sm font-bold text-violet-700 transition hover:bg-violet-50"
            >
              Descubrir negocios <ArrowUpRight size={17} />
            </Link>
          </div>
        </div>
      </section>

      {/* Ofertas */}
      <section className="px-5 py-12 md:px-10">
        <div className="mx-auto max-w-6xl">
          <SectionHeader
            eyebrow="Oportunidades para ti"
            title="Ofertas que destacan"
            description="Encuentra algo especial a un mejor precio."
          />
          <div className="grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-4">
            {products
              .filter((product) => product.oldPrice)
              .map((product) => (
                <ProductCard key={product.id} product={product} />
              ))}
          </div>
        </div>
      </section>

      {/* Tiendas */}
      <section className="bg-zinc-50 px-5 py-12 dark:bg-zinc-900/50 md:px-10">
        <div className="mx-auto max-w-6xl">
          <SectionHeader
            eyebrow="Personas y negocios"
            title="Conoce a tus próximos favoritos"
            description="Negocios locales que merecen un lugar en tu mapa."
            href="/tiendas"
          />

          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
            {stores.map((store) => (
              <StoreCard key={store.id} store={store} />
            ))}
          </div>
        </div>
      </section>

      {/* Ocasiones */}
      <section className="px-5 py-12 md:px-10">
        <div className="mx-auto max-w-6xl">
          <SectionHeader
            eyebrow="Inspírate"
            title="¿Qué tienes en mente?"
            description="Dinos qué plan tienes y descubre opciones."
          />

          <div className="flex gap-2 overflow-x-auto pb-3">
            {occasions.map(({ id, label, icon: Icon }) => (
              <button
                key={id}
                type="button"
                onClick={() => setActiveOccasion(activeOccasion === id ? "" : id)}
                className={`flex shrink-0 items-center gap-2 rounded-full border px-4 py-3 text-xs font-semibold transition ${
                  activeOccasion === id
                    ? "border-violet-600 bg-violet-600 text-white"
                    : "border-zinc-200 hover:border-violet-300 dark:border-zinc-800"
                }`}
              >
                <Icon size={16} /> {label}
              </button>
            ))}
          </div>

          <div className="mt-5 grid grid-cols-2 gap-4 sm:grid-cols-4">
            {occasionProducts.slice(0, 4).map((product) => (
              <ProductCard key={product.id} product={product} />
            ))}
          </div>
        </div>
      </section>

      {/* Rutas */}
      <section className="px-5 pb-14 pt-5 md:px-10">
        <div className="mx-auto max-w-6xl">
          <SectionHeader
            eyebrow="Recorre la ciudad"
            title="Rutas para disfrutar Guayaquil"
            description="Ideas para salir, explorar y descubrir nuevos lugares."
            href="/rutas"
          />

          <div className="grid gap-4 sm:grid-cols-3">
            {[
              { emoji: "☕", title: "Mañana de café", detail: "Cafés y rincones para empezar el día.", count: "3 paradas", color: "from-amber-100 to-orange-200" },
              { emoji: "🛍️", title: "Tarde de compras", detail: "Marcas locales, moda y accesorios.", count: "5 paradas", color: "from-pink-100 to-rose-200" },
              { emoji: "🍜", title: "Sabores locales", detail: "Una ruta para probar algo diferente.", count: "4 paradas", color: "from-emerald-100 to-teal-200" },
            ].map((route) => (
              <Link
                href="/rutas"
                key={route.title}
                className="group overflow-hidden rounded-2xl border border-zinc-200/80 transition hover:-translate-y-1 hover:shadow-lg dark:border-zinc-800"
              >
                <div className={`flex h-36 items-center justify-center bg-gradient-to-br ${route.color}`}>
                  <span className="text-6xl transition group-hover:scale-110">{route.emoji}</span>
                </div>
                <div className="p-5">
                  <span className="text-[10px] font-bold uppercase tracking-wider text-violet-600">{route.count}</span>
                  <h3 className="mt-2 font-bold">{route.title}</h3>
                  <p className="mt-1 text-xs leading-5 text-zinc-500">{route.detail}</p>
                  <span className="mt-4 inline-flex items-center gap-1 text-xs font-semibold">
                    Ver recorrido <ArrowRight size={14} />
                  </span>
                </div>
              </Link>
            ))}
          </div>
        </div>
      </section>

      {/* CTA final */}
      <section className="px-5 pb-16 md:px-10">
        <div className="mx-auto flex max-w-6xl flex-col items-start justify-between gap-6 rounded-3xl border border-zinc-200 bg-white p-6 dark:border-zinc-800 dark:bg-zinc-900 sm:flex-row sm:items-center sm:p-10">
          <div className="max-w-lg">
            <p className="mb-2 text-xs font-bold uppercase tracking-widest text-violet-600">
              ¿Tienes un negocio?
            </p>
            <h2 className="text-2xl font-bold tracking-tight sm:text-3xl">
              Tu próximo cliente puede estar aquí.
            </h2>
            <p className="mt-3 text-sm leading-6 text-zinc-500">
              Dale visibilidad a tu negocio y forma parte de una nueva manera
              de descubrir el comercio local.
            </p>
          </div>
          <Link
            href="/login"
            className="inline-flex shrink-0 items-center gap-2 rounded-xl bg-violet-600 px-5 py-3.5 text-sm font-semibold text-white transition hover:bg-violet-700"
          >
            Quiero mi tienda <ArrowRight size={17} />
          </Link>
        </div>
      </section>
    </div>
  );
}
